# Check the structure of search results
results = await CONTEXT.search("[grade]")
print(type(results))
if isinstance(results, list):
    print(f"len={len(results)}")
    if results:
        print(type(results[0]), results[0])
elif isinstance(results, dict):
    print(results.keys())
    for k, v in results.items():
        print(f"{k}: {type(v)} {str(v)[:200]}")
else:
    print(str(results)[:500])
